// Mettez ici le nom EXACT du nœud qui contient la facture OCR complète.
// Ce nœud doit avoir document.numero = "110001397".
const SOURCE_NODE_NAME = 'Code Restore Data';

function readNode(nodeName) {
  try {
    return $(nodeName).first().json || {};
  } catch (error) {
    return {};
  }
}

function firstNonEmpty(values) {
  for (const value of values) {
    if (
      value !== undefined &&
      value !== null &&
      String(value).trim() !== ''
    ) {
      return String(value).trim();
    }
  }

  return '';
}

function sanitizeFileName(value) {
  return String(value)
    .trim()
    .replace(/[\\/:*?"<>|]/g, '_');
}

const sourceData = readNode(SOURCE_NODE_NAME);

return items.map(item => {
  const xml =
    item.json.xml ||
    item.json.signed_xml ||
    '';

  if (!xml) {
    throw new Error(
      'XML signé introuvable. Champs disponibles : ' +
      JSON.stringify(Object.keys(item.json))
    );
  }

  // 1. Chercher dans le XML
  const documentMatch = xml.match(
    /<DocumentIdentifier[^>]*>\s*([^<]+?)\s*<\/DocumentIdentifier>/i
  );

  let invoiceNumber =
    documentMatch?.[1]?.trim() || '';

  let invoiceNumberSource = invoiceNumber
    ? 'DocumentIdentifier'
    : '';

  // 2. Chercher dans l’item courant
  if (!invoiceNumber) {
    invoiceNumber = firstNonEmpty([
      item.json.invoice_number,

      item.json.document?.numero,
      item.json.facture?.numero,

      item.json.data?.document?.numero,
      item.json.data?.facture?.numero,

      item.json.corrected_data?.document?.numero,
      item.json.corrected_data?.facture?.numero,

      item.json.original_data?.document?.numero,
      item.json.original_data?.facture?.numero,
    ]);

    if (invoiceNumber) {
      invoiceNumberSource = 'item courant';
    }
  }

  // 3. Chercher dans le nœud OCR/source
  if (!invoiceNumber) {
    invoiceNumber = firstNonEmpty([
      sourceData.invoice_number,

      sourceData.document?.numero,
      sourceData.facture?.numero,

      sourceData.data?.document?.numero,
      sourceData.data?.facture?.numero,

      sourceData.corrected_data?.document?.numero,
      sourceData.corrected_data?.facture?.numero,
    ]);

    if (invoiceNumber) {
      invoiceNumberSource = SOURCE_NODE_NAME;
    }
  }

  // 4. Chercher dans les corrections humaines
  if (!invoiceNumber) {
    const correctedNode =
      readNode('Appliquer corrections humaines');

    invoiceNumber = firstNonEmpty([
      correctedNode.corrected_data?.document?.numero,
      correctedNode.corrected_data?.facture?.numero,
      correctedNode.document?.numero,
      correctedNode.facture?.numero,
    ]);

    if (invoiceNumber) {
      invoiceNumberSource =
        'Appliquer corrections humaines';
    }
  }

  // 5. Chercher dans la revalidation
  if (!invoiceNumber) {
    const revalidationNode =
      readNode('Revalidation après correction');

    invoiceNumber = firstNonEmpty([
      revalidationNode.data?.document?.numero,
      revalidationNode.data?.facture?.numero,

      revalidationNode.corrected_data?.document?.numero,
      revalidationNode.corrected_data?.facture?.numero,

      revalidationNode.document?.numero,
      revalidationNode.facture?.numero,
    ]);

    if (invoiceNumber) {
      invoiceNumberSource =
        'Revalidation après correction';
    }
  }

  if (!invoiceNumber) {
    throw new Error(
      `Numéro de facture introuvable. Vérifiez que le nœud ` +
      `"${SOURCE_NODE_NAME}" existe exactement avec ce nom. ` +
      `Clés trouvées dans ce nœud : ` +
      JSON.stringify(Object.keys(sourceData))
    );
  }

  const safeInvoiceNumber =
    sanitizeFileName(invoiceNumber);

  const fileName =
    `${safeInvoiceNumber}_signed.xml`;

  return {
    json: {
      ...item.json,
      invoice_number: safeInvoiceNumber,
      file_name: fileName,
      invoice_number_source: invoiceNumberSource,
    },

    binary: {
      ...(item.binary || {}),

      data: {
        data: Buffer
          .from(xml, 'utf8')
          .toString('base64'),

        mimeType: 'application/xml',
        fileExtension: 'xml',
        fileName,
      },
    },
  };
});

return items.map(item => {
  const restoredData =
    item.json.data ??
    item.json.corrected_data ??
    item.json;

  if (
    !restoredData ||
    typeof restoredData !== 'object' ||
    Array.isArray(restoredData)
  ) {
    throw new Error(
      'Données de facture introuvables. Champs disponibles : ' +
      JSON.stringify(Object.keys(item.json))
    );
  }

  return {
    json: restoredData,
    binary: item.binary,
  };
});

return items.map(item => {
  return {
    json: {
      xml_content: item.json.xml
    }
  };
});

